/**
 * 标签
 */
export interface Tag {
    /** 标签键 */
    Key?: string;
    /** 标签值 */
    Value?: string;
}
/**
 * 沙箱实例元数据项
 * 被如下接口引用：DescribeSandboxInstanceList, StartSandboxInstance, UpdateSandboxInstance
 */
export interface MetadataVar {
    /** 沙箱元数据名 */
    Name?: string;
    /** 沙箱元数据值 */
    Value?: string;
}
/**
 * VPC 网络相关配置
 * 被如下接口引用：CreateSandboxTool, DescribeSandboxToolList, UpdateSandboxTool
 */
export interface VPCConfig {
    /** VPC 子网 ID 列表 */
    SubnetIds?: string[];
    /** 安全组 ID 列表 */
    SecurityGroupIds?: string[];
}
/**
 * 沙箱网络配置
 * 被如下接口引用：CreateSandboxTool, DescribeSandboxToolList, UpdateSandboxTool
 */
export interface NetworkConfiguration {
    /** 网络模式（当前支持 PUBLIC, VPC, SANDBOX） */
    NetworkMode: string;
    /** VPC 网络相关配置 */
    VpcConfig?: VPCConfig;
}
/**
 * 环境变量
 */
export interface EnvVar {
    /** 环境变量名称 */
    Name: string;
    /** 环境变量值 */
    Value: string;
}
/**
 * 端口配置
 */
export interface PortConfiguration {
    /** 端口名 */
    Name?: string;
    /** 端口 */
    Port?: number;
    /** 协议 */
    Protocol?: string;
}
/**
 * 资源配置
 */
export interface ResourceConfiguration {
    /** CPU 资源量，示例值：500m */
    CPU?: string;
    /** 内存资源量，示例值：1Gi */
    Memory?: string;
}
/**
 * HTTP GET 探测动作配置
 */
export interface HttpGetAction {
    /** 路径 */
    Path?: string;
    /** 端口 */
    Port?: number;
    /** 协议 */
    Scheme?: string;
}
/**
 * 健康检查探针配置
 */
export interface ProbeConfiguration {
    /** HTTP GET 探测配置 */
    HttpGet?: HttpGetAction;
    /** 健康检查就绪超时（毫秒） */
    ReadyTimeoutMs?: number;
    /** 健康检查单次探测超时（毫秒） */
    ProbeTimeoutMs?: number;
    /** 健康检查间隔（毫秒） */
    ProbePeriodMs?: number;
    /** 健康检查成功阈值 */
    SuccessThreshold?: number;
    /** 健康检查失败阈值 */
    FailureThreshold?: number;
}
/**
 * 沙箱自定义 DNS 配置
 */
export interface DNSConfig {
    /** DNS 服务器地址，需要有效 IP 地址，默认值：10.0.0.1 */
    Servers: string[];
    /** 搜索域（对应 resolv.conf 的 search 指令） */
    Searches?: string[];
    /** 配置项（对应 resolv.conf 选项） */
    Options?: string[];
}
/**
 * 沙箱自定义配置
 * 被如下接口引用：CreateSandboxTool, StartSandboxInstance, UpdateSandboxTool
 */
export interface CustomConfiguration {
    /** 镜像地址 */
    Image?: string;
    /** 镜像仓库类型：enterprise、personal */
    ImageRegistryType?: string;
    /** 启动命令 */
    Command?: string[];
    /** 启动参数 */
    Args?: string[];
    /** 环境变量 */
    Env?: EnvVar[];
    /** 端口配置 */
    Ports?: PortConfiguration[];
    /** 资源配置 */
    Resources?: ResourceConfiguration;
    /** 探针配置 */
    Probe?: ProbeConfiguration;
    /** 沙箱 DNS 配置 */
    DNSConfig?: DNSConfig;
}
/**
 * UpdateSandboxTool 请求参数
 */
export interface UpdateSandboxToolOptions {
    /** 沙箱工具 ID，如 sdt-dibk4rra */
    toolId: string;
    /** 沙箱工具描述，最大长度 200 字符 */
    description?: string;
    /** 网络配置 */
    networkConfiguration?: NetworkConfiguration;
    /** 标签 */
    tags?: Tag[];
    /** 沙箱工具自定义配置 */
    customConfiguration?: CustomConfiguration;
}
/**
 * UpdateSandboxTool 返回结果
 */
export interface UpdateSandboxToolResp {
    /** 唯一请求 ID */
    RequestId: string;
}
/**
 * 过滤列表规则
 * 被如下接口引用：DescribeSandboxInstanceList, DescribeSandboxToolList
 */
export interface Filter {
    /** 属性名称，若存在多个 Filter 时，Filter 间的关系为逻辑与（AND） */
    Name?: string;
    /** 属性值，若同一个 Filter 存在多个 Values，同一 Filter 下 Values 间的关系为逻辑或（OR） */
    Values?: string[];
}
/**
 * 对象存储桶挂载配置
 * 被如下接口引用：CreateSandboxTool, DescribeSandboxToolList
 */
export interface CosStorageSource {
    /** 对象存储访问域名 */
    Endpoint?: string;
    /** 对象存储桶名称 */
    BucketName?: string;
    /** 对象存储桶路径，必须为以 / 起始的绝对路径 */
    BucketPath?: string;
}
/**
 * 镜像卷挂载源配置
 * 被如下接口引用：CreateSandboxTool, DescribeSandboxToolList
 */
export interface ImageStorageSource {
    /** 镜像地址 */
    Reference?: string;
    /** 镜像仓库类型：enterprise、personal */
    ImageRegistryType?: string;
    /** 镜像内部的路径 */
    SubPath?: string;
    /** 镜像 Digest，请求时无需传入 */
    Digest?: string;
}
/**
 * 文件存储配置
 * 被如下接口引用：CreateSandboxTool, DescribeSandboxToolList
 */
export interface CfsStorageSource {
    /** CFS 资源 ID */
    FileSystemId?: string;
    /** CFS 挂载路径 */
    Path?: string;
}
/**
 * 挂载存储配置
 * 被如下接口引用：CreateSandboxTool, DescribeSandboxToolList
 */
export interface StorageSource {
    /** 对象存储桶配置 */
    Cos?: CosStorageSource;
    /** 镜像卷配置 */
    Image?: ImageStorageSource;
    /** 文件存储配置 */
    Cfs?: CfsStorageSource;
}
/**
 * 沙箱工具中实例存储挂载配置
 * 被如下接口引用：CreateSandboxTool, DescribeSandboxToolList
 */
export interface StorageMount {
    /** 存储挂载配置名称 */
    Name?: string;
    /** 存储配置 */
    StorageSource?: StorageSource;
    /** 沙箱实例本地挂载路径 */
    MountPath?: string;
    /** 存储挂载读写权限配置，默认为 false */
    ReadOnly?: boolean;
}
/**
 * 沙箱自定义配置详细信息（响应用，与写入用的 CustomConfiguration 区分）
 * 被如下接口引用：DescribeSandboxInstanceList, DescribeSandboxToolList, StartSandboxInstance
 */
export interface CustomConfigurationDetail {
    /** 镜像地址 */
    Image?: string;
    /** 镜像仓库类型：TCR、CCR */
    ImageRegistryType?: string;
    /** 镜像 Digest */
    ImageDigest?: string;
    /** 启动命令 */
    Command?: string[];
    /** 启动参数 */
    Args?: string[];
    /** 环境变量 */
    Env?: EnvVar[];
    /** 端口配置 */
    Ports?: PortConfiguration[];
    /** 资源配置 */
    Resources?: ResourceConfiguration;
    /** 探针配置 */
    Probe?: ProbeConfiguration;
    /** 沙箱 DNS 配置 */
    DNSConfig?: DNSConfig;
}
/**
 * CLS 日志推送配置
 * 被如下接口引用：CreateSandboxTool, DescribeSandboxToolList
 */
export interface CLSConfig {
    /** 沙箱工具日志推送所使用的 CLS 日志主题 ID */
    TopicId?: string;
}
/**
 * 沙箱工具日志采集相关配置
 * 被如下接口引用：CreateSandboxTool, DescribeSandboxToolList
 */
export interface LogConfiguration {
    /** 日志推送 CLS 的配置 */
    CLSConfig?: CLSConfig;
}
/**
 * 沙箱工具结构体
 * 被如下接口引用：DescribeSandboxToolList
 */
export interface SandboxTool {
    /** 沙箱工具唯一标识符 */
    ToolId: string;
    /** 沙箱工具名称，长度 1-50 字符 */
    ToolName?: string;
    /** 沙箱工具类型：browser、code-interpreter、computer、mobile */
    ToolType?: string;
    /** 沙箱工具状态：CREATING、ACTIVE、DELETING、FAILED */
    Status?: string;
    /** 沙箱工具描述信息，最大长度 200 字符 */
    Description?: string;
    /** 默认超时时间（秒） */
    DefaultTimeoutSeconds?: number;
    /** 网络配置 */
    NetworkConfiguration?: NetworkConfiguration;
    /** 标签 */
    Tags?: Tag[];
    /** 创建时间，格式：ISO8601 */
    CreateTime?: string;
    /** 更新时间，格式：ISO8601 */
    UpdateTime?: string;
    /** 沙箱工具绑定角色 ARN */
    RoleArn?: string;
    /** 实例存储挂载配置 */
    StorageMounts?: StorageMount[];
    /** 沙箱工具自定义配置 */
    CustomConfiguration?: CustomConfigurationDetail;
    /** 日志推送相关配置 */
    LogConfiguration?: LogConfiguration;
    /** 用于说明沙箱工具处于该状态的原因 */
    StatusReason?: string;
}
/**
 * DescribeSandboxToolList 请求参数
 */
export interface DescribeSandboxToolListOptions {
    /** 沙箱工具 ID 列表，为空则查询所有，最大支持 100 个 */
    toolIds?: string[];
    /** 偏移量，默认为 0 */
    offset?: number;
    /** 返回数量，默认为 20，最大值为 100 */
    limit?: number;
    /** 过滤条件 */
    filters?: Filter[];
}
/**
 * DescribeSandboxToolList 返回结果
 */
export interface DescribeSandboxToolListResp {
    /** 沙箱工具列表 */
    SandboxToolSet: SandboxTool[];
    /** 符合条件的沙箱工具总数 */
    TotalCount: number;
    /** 唯一请求 ID */
    RequestId: string;
}
/**
 * CreateSandboxTool 请求参数
 */
export interface CreateSandboxToolOptions {
    /** 沙箱工具名称，长度 1-50 字符，支持英文、数字、下划线和连接线。同一 AppId 下名称必须唯一 */
    toolName: string;
    /** 沙箱工具类型：browser、code-interpreter、custom */
    toolType: string;
    /** 网络配置 */
    networkConfiguration: NetworkConfiguration;
    /** 沙箱工具描述，最大长度 200 字符 */
    description?: string;
    /** 默认超时时间，支持格式：5m、300s、1h 等，不指定则使用系统默认值（5 分钟），最大 24 小时 */
    defaultTimeout?: string;
    /** 标签 */
    tags?: Tag[];
    /** 幂等性 Token，长度不超过 64 字符 */
    clientToken?: string;
    /** 角色 ARN */
    roleArn?: string;
    /** 沙箱工具存储配置 */
    storageMounts?: StorageMount[];
    /** 沙箱工具自定义配置 */
    customConfiguration?: CustomConfiguration;
    /** 沙箱工具日志推送相关配置 */
    logConfiguration?: LogConfiguration;
}
/**
 * CreateSandboxTool 返回结果
 */
export interface CreateSandboxToolResp {
    /** 创建的沙箱工具 ID */
    ToolId: string;
    /** 唯一请求 ID */
    RequestId: string;
}
